const icons={shield:'<path d="M12 3 21 6v6c0 6-9 10-9 10S3 18 3 12V6z"/><path d="m8 12 3 3 5-6"/>',home:'<path d="m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9"/>',file:'<path d="M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h6"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>',history:'<path d="M3 4v6h6M3 10a9 9 0 1 1 1 7M12 7v6l4 2"/>',chart:'<path d="M4 21V12h3v9M11 21V7h3v14M18 21V3h3v18"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3z"/>',chevron:'<path d="m7 10 5 5 5-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<path d="M6 3h12M6 21h12M7 3v4l5 5-5 5v4M17 3v4l-5 5 5 5v4"/>',camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3z"/><circle cx="12" cy="13" r="4"/>',check:'<path d="m5 12 4 4L19 6"/>',alert:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>',more:'<path d="M5 12h.01M12 12h.01M19 12h.01"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.file}</svg>`;
function hydrate(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
const cases=[{id:'DX-1042',document:'Passport + visa',finding:'Birth date mismatch',next:'Compare evidence',time:'10:42',status:'Awaiting review'},{id:'DX-1041',document:'Passport',finding:'Glare over portrait',next:'Recapture image',time:'10:36',status:'Recapture needed'},{id:'DX-1040',document:'Permit',finding:'Expiry date passed',next:'Officer review',time:'10:29',status:'Awaiting review'},{id:'DX-1039',document:'National ID',finding:'Unsupported format',next:'Manual inspection',time:'10:21',status:'Awaiting review'},{id:'DX-1038',document:'Passport',finding:'Face check inconclusive',next:'Review capture',time:'10:15',status:'Awaiting review'},{id:'DX-1037',document:'Visa',finding:'Stamp needs review',next:'Inspect source',time:'10:08',status:'Awaiting review'}];
let currentCase=cases[0],selectedDoc='passport',imageMode='original',screenStage='review',reviewCount=0,recaptureCount=0,toastTimer;
const decisions=[];
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${action}">${label}</button>`;
function heading(title,sub,action='',eyebrow='DOCUMENT SCREENING'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function stats(){return `<div class="stats">${[['24','Demo cases today','file',''],[String(Math.max(0,6-reviewCount)),'Awaiting review','clock','amber'],[String(3+recaptureCount),'Recapture needed','camera','amber'],[String(15+reviewCount),'Reviews completed','check','green']].map(([n,t,i,c])=>`<div class="stat ${c}"><div class="number">${n}</div><div class="stat-icon">${icon(i)}</div><p>${t}</p></div>`).join('')}</div>`;}
function caseRows(list){return list.map(c=>`<tr><td class="case-number">${c.id}<span class="case-sub">Today, ${c.time}</span></td><td>${c.document}</td><td><span class="finding-dot"></span>${c.finding}</td><td>${c.next}</td><td><button class="table-action" data-open="${c.id}">Open case</button></td></tr>`).join('');}
function caseTable(list){return `<div class="table-scroll"><table><thead><tr><th>Case</th><th>Document</th><th>Finding</th><th>Next step</th><th>Action</th></tr></thead><tbody id="case-rows">${caseRows(list)}</tbody></table></div>`;}
function coverage(){return `<div class="card"><div class="card-title"><h2>Verification coverage</h2></div>${[['OCR + rules','Available',''],['Image screening','Demo model','blue'],['Face comparison','Demo model','blue'],['Issuer / blacklist status','Not connected','gray']].map(([a,b,c])=>`<div class="coverage-row"><span>${a}</span><span class="coverage-state"><i class="dot ${c}"></i>${b}</span></div>`).join('')}</div>`;}
function overview(){return heading('Screening overview','A clear view of cases awaiting officer review.',`<a class="button" href="#screening">${icon('plus')}New screening</a>`)+stats()+`<div class="overview-grid"><section class="card"><div class="card-title"><h2>Review queue</h2><span class="meta">Recent cases</span></div>${caseTable(cases.slice(0,5))}<div class="queue-bottom"><span>Showing 5 of 6 demo cases</span><a href="#queue" class="button text">View full queue ${icon('arrow')}</a></div></section><div class="overview-aside">${coverage()}<div class="info-note">${icon('info')}<div><h3>Officer decisions remain separate from screening results.</h3><p>Review evidence and record a reason before closing a case.</p></div></div></div></div>`;}
function docVisual(type='passport',extra=''){return `<div class="doc-visual ${type==='visa'?'visa':''} ${extra}"><img src="assets/document-reference.jpg" alt="Fictional ${type} specimen for Demo Person"></div>`;}
function steps(){return `<div class="steps"><span class="step"><b>${icon('check')}</b>Capture</span><i class="step-line"></i><span class="step"><b>${icon('check')}</b>Extract</span><i class="step-line"></i><span class="step active"><b>3</b>Review</span></div>`;}
function checkRow(label,status,tone=''){return `<div class="check-row"><span class="check-icon ${tone}">${icon(tone==='amber'?'alert':tone==='gray'?'more':'check')}</span><span class="check-label">${label}</span><span class="check-status ${tone}">${status}</span></div>`;}
function screening(){if(screenStage==='capture')return heading('Capture a document','Case DX-1042 · Passport and visa')+`<div class="card capture-panel"><span>${icon('camera')}</span><h2>Document capture</h2><p>Use the supplied fictional passport and visa to preview the screening workflow.</p>${button('Load demo documents','load-demo')}<p class="fineprint">This interface preview does not process identity documents.</p></div>`;return heading('Screen a document','Case DX-1042 · Passport and visa',steps())+`<div class="screen-grid"><section class="card"><div class="card-title"><h2>Document image</h2><select class="select" id="image-mode" aria-label="Document image view"><option value="original" ${imageMode==='original'?'selected':''}>Original</option><option value="highlighted" ${imageMode==='highlighted'?'selected':''}>Highlighted fields</option></select></div><div class="document-body">${docVisual(selectedDoc,imageMode==='highlighted'?'overlay':'')}<div class="thumbs"><button class="thumb ${selectedDoc==='passport'?'active':''}" data-document="passport">${docVisual()}<span>Passport</span></button><button class="thumb ${selectedDoc==='visa'?'active':''}" data-document="visa">${docVisual('visa')}<span>Visa</span></button></div><p class="image-caption">${icon('lock')}Fictional specimen · Provided reference</p></div></section><section class="card"><div class="card-title"><h2>Extracted fields</h2></div><div class="fields"><div class="field"><span>Full name</span><strong>DEMO PERSON</strong></div><div class="field flagged"><span>Birth date · passport</span><strong>12 APR 1994</strong></div><div class="field"><span>Birth date · visa</span><strong>12 APR 1995</strong></div><div class="field"><span>Passport expiry</span><strong>12 APR 2034</strong></div></div><div class="warning-note"><h3>${icon('alert')}Birth dates disagree</h3><p>Confirm both source fields before escalating.</p><a class="button secondary" href="#case/DX-1042">Compare source regions</a></div></section><section class="card checks-card"><div class="card-title"><h2>Screening checks</h2></div><div class="checks-list">${checkRow('Capture quality','Usable')}${checkRow('Field consistency','Mismatch found','amber')}${checkRow('Image tampering','No supported anomaly detected')}${checkRow('Face comparison','Not performed','gray')}${checkRow('External status','Not checked','gray')}</div><div class="checks-footer">${button('Request recapture','recapture',true)}<a class="button" href="#case/DX-1042">Send for officer review</a><p class="fineprint">A completed check does not establish document authenticity.</p></div></section></div>`;}
function inlineStatus(text,tone=''){return `<span class="inline-status"><span class="check-icon ${tone}">${icon(tone==='amber'?'alert':tone==='gray'?'more':'check')}</span>${text}</span>`;}
function review(){const c=currentCase,isMismatch=c.id==='DX-1042',record=decisions.find(d=>d.id===c.id);return `<div class="page-heading"><div><div class="eyebrow"><a href="#queue">Review queue</a> / Case details</div><div class="heading-inline"><h1>Case ${c.id}</h1><span class="badge">${record?'Action recorded':'Officer review required'}</span></div><p>${c.document.replace(' + ',' and ')} · DEMO PERSON</p></div><a class="button secondary small" href="#screening">View documents</a></div><div class="alert"><span>${icon('alert')}</span><div><h3>${c.finding}</h3><p>${isMismatch?'Two readable source fields disagree. Confirm the documents and record the next action.':'Review the demo finding and record the appropriate follow-up action.'}</p></div></div><div class="review-grid"><section class="card padded"><h2>${isMismatch?'Evidence comparison':'Document evidence'}</h2>${isMismatch?`<div class="evidence-pair"><div class="evidence"><div class="evidence-label">Passport · Original crop</div><div class="evidence-image"><img src="assets/evidence-reference.jpg" alt="Passport date of birth: 12 APR 1994, with the year highlighted"></div></div><div class="evidence"><div class="evidence-label">Visa · Original crop</div><div class="evidence-image visa"><img src="assets/evidence-reference.jpg" alt="Visa date of birth: 12 APR 1995, with the year highlighted"></div></div></div>`:`<div class="info-note"><span>${icon('file')}</span><div><h3>${c.document} screening</h3><p>${c.finding}. Source imagery for this additional demo case is not included.</p></div></div><br>`}<h3>Check results</h3><div class="checks-table"><table><thead><tr><th>Check</th><th>Result</th><th>Limitation</th></tr></thead><tbody><tr><td>${isMismatch?'Field comparison':'Document screening'}</td><td>${inlineStatus(isMismatch?'Mismatch':c.finding,'amber')}</td><td>Requires officer confirmation</td></tr><tr><td>Image screening</td><td>${inlineStatus('No supported anomaly detected')}</td><td>Does not establish authenticity</td></tr><tr><td>Face comparison</td><td>${inlineStatus('Not performed','gray')}</td><td>Live capture required</td></tr><tr><td>Issuer / blacklist status</td><td>${inlineStatus('Not checked','gray')}</td><td>No live connection</td></tr></tbody></table></div></section><section class="card padded"><form class="officer-form" id="officer-form"><h2>Officer action</h2><div class="radio-options">${['Request another capture','Refer for secondary inspection','Record resolved discrepancy'].map((a,i)=>`<label class="radio-option"><input type="radio" name="officer-action" value="${a}" ${(record?record.action===a:i===1)?'checked':''}>${a}</label>`).join('')}</div><div class="reason-block"><label for="officer-reason">Reason for action</label><textarea id="officer-reason" maxlength="500" rows="4" required>${escapeHtml(record?.reason||(isMismatch?'Birth dates differ across the submitted documents. Further verification required.':''))}</textarea><div class="char-count"><span id="reason-count">0</span>/500</div></div><button class="button" type="submit">${record?'Update officer decision':'Record officer decision'}</button><p class="fineprint">This records a review action, not travel clearance.</p></form></section></div><section class="card history-card"><h2>Case history</h2><div class="timeline"><div class="timeline-event"><strong>${c.time}</strong>Documents captured<small>Demo capture session</small></div><div class="timeline-event"><strong>10:43</strong>${isMismatch?'Field mismatch detected':'Screening finding recorded'}<small>Demo screening results</small></div><div class="timeline-event"><strong>10:44</strong>Officer opened evidence<small>Demo Officer</small></div>${record?`<div class="timeline-event"><strong>${record.time}</strong>Officer action recorded<small>${escapeHtml(record.action)}</small></div>`:''}</div></section>`;}
function queue(){return heading('Review queue','Review findings, compare evidence, and record the next action.',`<a class="button" href="#screening">${icon('plus')}New screening</a>`)+`<section class="card"><div class="toolbar"><input type="search" class="search" id="queue-search" aria-label="Search cases" placeholder="Search case, document, or finding…"><select class="select" id="queue-filter" aria-label="Filter cases"><option>All cases</option><option>Awaiting review</option><option>Recapture needed</option><option>Action recorded</option></select></div>${caseTable(cases)}<div id="queue-empty" class="empty" hidden>No matching cases. Try a different search.</div><div class="queue-bottom"><span id="queue-count">6 demo cases</span><span>Fictional screening data</span></div></section>`;}
function history(){return heading('Case history','A record of screening events and officer review actions.','', 'REVIEW RECORDS')+`<section class="card"><div class="card-title"><h2>Recent activity</h2><span class="meta">Current demo session</span></div><div class="table-scroll"><table><thead><tr><th>Time</th><th>Case</th><th>Activity</th><th>Recorded by</th><th>Details</th></tr></thead><tbody>${decisions.slice().reverse().map(d=>`<tr><td>${d.time}</td><td class="case-number">${d.id}</td><td>${escapeHtml(d.action)}</td><td>Demo Officer</td><td>${escapeHtml(d.reason)}</td></tr>`).join('')}${[['10:44','DX-1042','Evidence opened','Demo Officer','Passport and visa source regions'],['10:43','DX-1042','Field mismatch detected','Demo screening','Birth dates differ across documents'],['10:42','DX-1042','Documents captured','Demo Officer','Passport and visa'],['10:36','DX-1041','Recapture required','Demo screening','Glare over portrait']].map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><p class="fineprint">New actions remain in this preview session and reset when the page is reloaded.</p>`;}
function reports(){return heading('Screening reports','Demo workload and review outcomes at a glance.','', 'WORKSPACE REPORTS')+stats()+`<div class="report-grid"><section class="card padded"><h2>Review outcomes</h2>${[['Reviews completed',15+reviewCount,'#248c79'],['Awaiting review',Math.max(0,6-reviewCount),'#d69a35'],['Recapture needed',3+recaptureCount,'#5286d3']].map(([t,n,col])=>`<div class="bar-row"><span>${t}</span><div class="bar-track"><span style="width:${Math.min(100,n/24*100)}%;background:${col}"></span></div><strong>${n}</strong></div>`).join('')}<p class="fineprint">Illustrative counts for the 24-case demo workspace.</p></section>${coverage()}</div>`;}
function route(){const hash=location.hash.slice(1)||'overview';const [page,id]=hash.split('/');if(page==='case')currentCase=cases.find(c=>c.id===id)||cases[0];document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===(page==='case'?'queue':page);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('app').innerHTML=({overview,screening,queue,history,reports,case:review}[page]||overview)();document.title=`SeemaDrishti | ${{overview:'Overview',screening:'Document screening',queue:'Review queue',history:'Case history',reports:'Reports',case:'Officer review'}[page]||'Overview'}`;hydrate();const reason=document.getElementById('officer-reason');if(reason)document.getElementById('reason-count').textContent=reason.value.length;window.scrollTo(0,0);}
function toast(message){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=message;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,4500);}
function filterQueue(){const q=document.getElementById('queue-search').value.toLowerCase(),filter=document.getElementById('queue-filter').value;const list=cases.filter(c=>Object.values(c).join(' ').toLowerCase().includes(q)&&(filter==='All cases'||c.status===filter));document.getElementById('case-rows').innerHTML=caseRows(list);document.getElementById('queue-empty').hidden=!!list.length;document.getElementById('queue-count').textContent=`${list.length} demo case${list.length===1?'':'s'}`;}
document.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open){location.hash=`case/${open.dataset.open}`;return;}const thumb=e.target.closest('[data-document]');if(thumb){selectedDoc=thumb.dataset.document;route();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='recapture'){currentCase=cases[0];document.getElementById('recapture-case').textContent=currentCase.id;document.getElementById('capture-dialog').showModal();}if(action==='load-demo'){screenStage='review';route();toast('Demo documents loaded. Screening results are illustrative.');}});
document.addEventListener('input',e=>{if(e.target.id==='queue-search')filterQueue();if(e.target.id==='officer-reason')document.getElementById('reason-count').textContent=e.target.value.length;});
document.addEventListener('change',e=>{if(e.target.id==='image-mode'){imageMode=e.target.value;route();}if(e.target.id==='queue-filter')filterQueue();});
document.addEventListener('submit',e=>{if(e.target.id!=='officer-form')return;e.preventDefault();const reason=document.getElementById('officer-reason');if(!reason.value.trim()){reason.setCustomValidity('Enter a reason for this review action.');reason.reportValidity();reason.setCustomValidity('');return;}const action=new FormData(e.target).get('officer-action');let d=decisions.find(d=>d.id===currentCase.id);if(!d){d={id:currentCase.id};decisions.push(d);reviewCount++;}Object.assign(d,{action,reason:reason.value.trim(),time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});currentCase.status='Action recorded';currentCase.next=action==='Request another capture'?'Recapture image':'Action recorded';route();toast('Officer decision recorded in this demo session.');});
document.getElementById('profile-button').addEventListener('click',()=>{const el=document.getElementById('profile-menu');el.hidden=!el.hidden;document.getElementById('profile-button').setAttribute('aria-expanded',String(!el.hidden));});
document.getElementById('cancel-capture').addEventListener('click',()=>document.getElementById('capture-dialog').close());
document.getElementById('confirm-capture').addEventListener('click',()=>{const c=currentCase;c.status='Recapture needed';c.next='Recapture image';recaptureCount++;document.getElementById('capture-dialog').close();screenStage='capture';route();toast('Recapture request recorded in this demo session.');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.getElementById('profile-menu').hidden=true;document.getElementById('profile-button').setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',route);hydrate();route();
